declare(strict_types=1);

/**
 * Adds to tests/fixtures/nextcloud-api/<major>.php the public surface of every Nextcloud Tables class the app names in
 * lib/ (plus the Tables entities of NextcloudApiUsage::EXTRA_CLASSES), parsed from the official Tables release pinned for
 * that major in tables-sources.json: the oldest Tables release for that Nextcloud that is not older than
 * AppEnablement::MINIMUM_VERSIONS. The Entity and QBMapper of the server release come along, so the magic getters of the
 * Tables entities are in the surface. The sources are only tokenized, never executed. Run it after generate.php, which
 * rewrites the fixtures without the Tables surfaces.
 *
 * Usage: php -d memory_limit=1G tests/fixtures/nextcloud-api/tables/generate-tables.php <34|35> <archive directory>
 *
 * <archive directory> holds tables-<version>.tar.gz and server-<version>-<Entity|QBMapper>.php of that major, downloaded
 * from the URL of tables-sources.json and from raw.githubusercontent.com/nextcloud/server/v<version>/<path>; every file
 * is checked against its SHA256 first.
 */

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\LibScanner;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\NextcloudApiUsage;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\Tables\TablesSourcePins;

require __DIR__ . '/../../../../vendor/autoload.php';

[, $major, $archives] = $argv + [null, null, null];
$fixtures = dirname(__DIR__);
if (!isset(TablesSourcePins::all()[(string)$major]) || !is_dir((string)$archives)) {
	fwrite(STDERR, "usage: php generate-tables.php <major of tables-sources.json> <verified archive directory>\n");
	exit(2);
}
$pin = TablesSourcePins::pin((string)$major);

/**
 * Refuses a file whose SHA256 is not the pinned one.
 *
 * @param string $file downloaded file
 * @param string $sha256 pinned checksum
 * @return void
 */
$verify = static function (string $file, string $sha256): void {
	if (!is_file($file) || hash_file('sha256', $file) !== $sha256) {
		throw new RuntimeException('Source SHA256 mismatch: ' . $file);
	}
};

$tree = sys_get_temp_dir() . '/mcp-tables-api-' . bin2hex(random_bytes(6));
mkdir($tree, recursive: true);
try {
	foreach ($pin['server']['files'] as $path => $sha256) {
		$file = $archives . '/server-' . $pin['server']['version'] . '-' . basename($path);
		$verify($file, $sha256);
		@mkdir($tree . '/' . dirname($path), recursive: true);
		copy($file, $tree . '/' . $path);
	}
	$archive = $archives . '/tables-' . $pin['tables']['version'] . '.tar.gz';
	$verify($archive, $pin['tables']['sha256']);
	$unpack = $tree . '/unpack';
	mkdir($unpack);
	(new PharData($archive))->extractTo($unpack);
	$roots = glob($unpack . '/*', GLOB_ONLYDIR) ?: [];
	if (count($roots) !== 1) {
		throw new RuntimeException('Expected one official app root');
	}
	mkdir($tree . '/apps');
	rename($roots[0], $tree . '/apps/tables');
	TablesSourcePins::verified($tree, (string)$major);

	$isTables = static fn (string $class): bool => str_starts_with($class, 'OCA\\Tables\\');
	$classes = array_values(array_unique(array_filter([
		...array_keys((new LibScanner(dirname(__DIR__, 4) . '/lib'))->classes()),
		...NextcloudApiUsage::EXTRA_CLASSES,
	], $isTables)));
	$file = $fixtures . '/' . $major . '.php';
	$fixture = require $file;
	$fixture['classes'] = array_filter($fixture['classes'], static fn (string $class): bool => !$isTables($class), ARRAY_FILTER_USE_KEY);
	$parser = new SourceParser($tree);
	foreach ($classes as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) {
			throw new RuntimeException('Official source lacks ' . $class);
		}
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$fixture['tablesSources'] = $pin;

	$original = (string)file_get_contents($file);
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// Tables surfaces generated[^\n]*\n~', '', $header);
	$header .= "// Tables surfaces generated by tables/generate-tables.php; official versions/SHAs in tablesSources.\n";
	FixtureFile::write($file, $header, $fixture);
	echo 'Generated Tables ' . $pin['tables']['version'] . ' surfaces for NC' . $major . ': ' . implode(', ', $classes) . "\n";
} finally {
	$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
	foreach ($files as $entry) {
		$entry->isDir() ? rmdir($entry->getPathname()) : unlink($entry->getPathname());
	}
	rmdir($tree);
}
